#include <iostream>
#include <vector>
#include <string>
#include <queue>
#include <map>

int main() {
    // 1. Vector memory management: reserve and shrink_to_fit
    std::vector<std::string> names{"Suzanne", "James", "Maria", "Juan"};
    std::cout << "Initial size: " << names.size() << ", capacity: " << (names.capacity() >= names.size()) << "\n";

    names.reserve(100);
    std::cout << "After reserve(100) capacity: " << (names.capacity() >= 100) << "\n";

    names.shrink_to_fit();
    std::cout << "After shrink_to_fit() capacity: " << (names.capacity() >= names.size()) << "\n";

    // 2. Map subscript behavior
    std::map<std::string, int> scores;
    scores["Alice"] = 95;
    std::cout << "Alice: " << scores["Alice"] << "\n";
    std::cout << "Accessing Bob with []: " << scores["Bob"] << "\n"; // inserts Bob with 0
    std::cout << "Map size after accessing Bob: " << scores.size() << "\n";

    // 3. Priority Queue: Highest priority out first
    std::priority_queue<int> pq;
    pq.push(15);
    pq.push(42);
    pq.push(8);
    std::cout << "Priority queue top: " << pq.top() << "\n";
    pq.pop();
    std::cout << "Next top after pop: " << pq.top() << "\n";

    return 0;
}

#include <iostream>
#include <vector>
#include <bitset>

template <typename T>
bool palindrome(const std::vector<T>& v) {
    if (v.empty()) return true;
    auto left = v.begin();
    auto right = v.end() - 1;
    while (left < right) {
        if (*left != *right) return false;
        ++left;
        --right;
    }
    return true;
}

int main() {
    // 1. Palindrome template verification
    std::vector<int> v1{1, 2, 3, 2, 1};
    std::vector<int> v2{1, 2, 3, 4};
    std::cout << "v1 is palindrome: " << (palindrome(v1) ? "true" : "false") << "\n";
    std::cout << "v2 is palindrome: " << (palindrome(v2) ? "true" : "false") << "\n";

    // 2. Sieve of Eratosthenes with std::bitset
    constexpr std::size_t LIMIT = 60;
    std::bitset<LIMIT> primes;
    primes.set(); // set all bits to 1
    primes.reset(0);
    primes.reset(1);

    for (std::size_t p = 2; p * p < LIMIT; ++p) {
        if (primes.test(p)) {
            for (std::size_t i = p * p; i < LIMIT; i += p) {
                primes.reset(i);
            }
        }
    }

    std::cout << "Primes up to " << LIMIT - 1 << ": ";
    for (std::size_t i = 2; i < LIMIT; ++i) {
        if (primes.test(i)) std::cout << i << " ";
    }
    std::cout << "\n";

    // 3. Prime factorization of 54
    int num = 54;
    std::cout << "The unique prime factorization of " << num << " is: ";
    bool first = true;
    for (std::size_t p = 2; p * p <= static_cast<std::size_t>(num); ++p) {
        while (num % p == 0) {
            if (!first) std::cout << " * ";
            std::cout << p;
            first = false;
            num /= static_cast<int>(p);
        }
    }
    if (num > 1) {
        if (!first) std::cout << " * ";
        std::cout << num;
    }
    std::cout << "\n";

    return 0;
}
